import { SubTrigger as RadixSubTrigger } from '@radix-ui/react-dropdown-menu';
import React, { forwardRef } from 'react';
import styled, { CSSObject } from 'styled-components';

import Borders from '@dynatrace/strato-design-tokens/borders';
import Colors from '@dynatrace/strato-design-tokens/colors';
import Spacings from '@dynatrace/strato-design-tokens/spacings';
import { ChevronRightSmallIcon } from '@dynatrace/strato-icons';

import { getItemSlots } from './item-slots.js';
import type { CSSFocusStylesObject } from '../../core/hooks/useFocusRing.js';
import { useFocusRing } from '../../core/hooks/useFocusRing.js';
import type { AriaLabelingProps } from '../../core/types/a11y-props.js';
import type { WithChildren } from '../../core/types/with-children.js';
import { mergeProps as _mergeProps } from '../../core/utils/merge-props.js';
import { TextBaseEmphasizedStyle } from '../../core/utils/styles/text-styles.js';
import { Flex } from '../../layouts-core/flex/Flex.js';

export interface MenuSubTriggerProps extends WithChildren, AriaLabelingProps {
  /**
   * Whether or not the menu trigger item is disabled.
   * If true, it prevents the user from interacting with the item.
   */
  disabled?: boolean;

  /**
   * Optional text used for typeahead purposes. By default, the typeahead
   * behavior will use the .textContent of the item. Use this when the content
   * is complex, or you have non-textual content inside.
   */
  textValue?: string;
}

const StyledSubTrigger = /* @__PURE__ */ styled(RadixSubTrigger)<{
  disabled?: boolean;
  $isFocusVisible?: boolean;
  $focusStyle?: CSSFocusStylesObject;
}>(({ disabled, $isFocusVisible, $focusStyle }) => {
  const disabledStyle: CSSObject = disabled
    ? {
        color: Colors.Text.Neutral.Disabled,
        cursor: 'default',
        pointerEvents: 'none',
      }
    : {
        color: Colors.Text.Neutral.Default,

        '&:hover': {
          color: Colors.Text.Neutral.Default,
          backgroundColor: Colors.Background.Field.Neutral.DefaultHover,
        },

        '&:active': {
          color: Colors.Text.Neutral.Default,
          backgroundColor: Colors.Background.Field.Neutral.DefaultActive,
        },
      };

  const focusStyle =
    !disabled && $isFocusVisible
      ? {
          ...$focusStyle,
          color: Colors.Text.Neutral.Default,
        }
      : $focusStyle;

  return {
    display: 'flex',

    backgroundColor: 'transparent',
    textAlign: 'start',
    paddingTop: Spacings.Size6,
    paddingRight: Spacings.Size8,
    paddingBottom: Spacings.Size6,
    paddingLeft: Spacings.Size8,

    cursor: 'pointer',

    borderColor: 'transparent',
    borderStyle: 'solid',
    borderWidth: 0,
    borderRadius: Borders.Radius.Field.Default,

    ...TextBaseEmphasizedStyle,
    ...focusStyle,
    ...disabledStyle,
  };
});

const StyledItemChildren = /* @__PURE__ */ styled('div')({
  flex: '1 1 auto',
  overflow: 'hidden',
  '&:first-child': {
    paddingLeft: Spacings.Size4,
  },
});

/**
 * An item that opens a submenu. Used in combination with a `Menu.Sub`.
 * Must not be rendered inside a root Menu.
 */
export const SubTrigger = /* @__PURE__ */ forwardRef<
  HTMLDivElement,
  MenuSubTriggerProps
>(
  (
    {
      children,
      disabled,
      'aria-label': ariaLabel,
      'aria-labelledby': ariaLabelledBy,
      'aria-describedby': ariaDescribedBy,
      'aria-details': ariaDetails,
      ...remainingProps
    }: MenuSubTriggerProps,
    forwardedRef,
  ) => {
    const slots = getItemSlots(children);

    const { focusProps, focusStyles, isFocusVisible } = useFocusRing();

    return (
      <StyledSubTrigger
        ref={forwardedRef}
        disabled={disabled}
        $isFocusVisible={isFocusVisible}
        $focusStyle={focusStyles}
        {..._mergeProps(remainingProps, focusProps)}
        aria-label={ariaLabel}
        aria-labelledby={ariaLabelledBy}
        aria-describedby={ariaDescribedBy}
        aria-details={ariaDetails}
        aria-haspopup={true}
        role="menuitem"
        asChild
      >
        <Flex justifyContent="space-between">
          {slots.icon}
          <StyledItemChildren className="item-children">
            {slots.freeform}
          </StyledItemChildren>
          <ChevronRightSmallIcon />
        </Flex>
      </StyledSubTrigger>
    );
  },
);

(SubTrigger as typeof SubTrigger & { displayName: string }).displayName =
  'Menu.SubTrigger';
